def process(wildfires_2008) -> pd.DataFrame:
    total = wildfires_2008['prim_threatened_aggregate'].sum()
    return pd.DataFrame({'total_damage': [total]})

def process(cumulative_damage_calculation) -> pd.DataFrame:
    # Find first row where cumulative percentage >= 90
    threshold_row = cumulative_damage_calculation[cumulative_damage_calculation['cumulative_pct'] >= 90.0]
    if len(threshold_row) > 0:
        fires_needed = threshold_row.iloc[0]['fire_count']
        return pd.DataFrame({'fires_for_90pct': [fires_needed]})
    else:
        return pd.DataFrame({'fires_for_90pct': [len(cumulative_damage_calculation)]})

def process(wildfires_2008) -> pd.DataFrame:
    total_count = len(wildfires_2008)
    return pd.DataFrame({'total_fires': [total_count]})

def process(fires_for_90_percent, total_fires_2008) -> pd.DataFrame:
    fires_needed = fires_for_90_percent['fires_for_90pct'].iloc[0]
    total_fires = total_fires_2008['total_fires'].iloc[0]
    percentage = (fires_needed / total_fires)
    return pd.DataFrame({'percentage_of_fires': [percentage]})
